Who owns reservation RSV-2291?:
SELECT r.reservation_id, r.serial, p.first_name, p.role, p.current_location
FROM reservations r JOIN people p ON p.person_id = r.owner_person_id
WHERE r.reservation_id = 'RSV-2291';

Where is drive unit SD9-R-0733 and what:
SELECT d.serial, d.model, d.status, d.condition, s.site_name, d.notes
FROM drive_units d JOIN sites s ON s.site_id = d.site_id
WHERE d.serial = 'SD9-R-0733';
